CREATE TABLE IF NOT EXISTS user (id BIGINT PRIMARY KEY AUTO_INCREMENT, phone VARCHAR(20) NOT NULL UNIQUE, nick_name VARCHAR(50) DEFAULT '邻里用户', icon VARCHAR(500) DEFAULT '', create_time DATETIME DEFAULT CURRENT_TIMESTAMP, update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, category VARCHAR(50), score DECIMAL(2,1) DEFAULT 5.0, address VARCHAR(255), business_hours VARCHAR(100), cover VARCHAR(500), status TINYINT DEFAULT 1, create_time DATETIME DEFAULT CURRENT_TIMESTAMP, update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupon (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, name VARCHAR(100), amount DECIMAL(10,2), threshold_amount DECIMAL(10,2), stock INT DEFAULT 0, begin_time DATETIME, end_time DATETIME, status TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, total_amount DECIMAL(10,2), status TINYINT DEFAULT 1, create_time DATETIME DEFAULT CURRENT_TIMESTAMP, pay_time DATETIME);
CREATE TABLE IF NOT EXISTS review (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, content VARCHAR(1000), score TINYINT, images VARCHAR(2000), create_time DATETIME DEFAULT CURRENT_TIMESTAMP);
